function loadProgress() {
  try {
    const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}')
    return {
      attempts: Array.isArray(value.attempts) ? value.attempts : [],
      wrongIds: Array.isArray(value.wrongIds) ? value.wrongIds : [],
      masteredIds: Array.isArray(value.masteredIds) ? value.masteredIds : [],
      testedKnowledgeIds: Array.isArray(value.testedKnowledgeIds) ? value.testedKnowledgeIds : [],
      knowledgeStats: value.knowledgeStats && typeof value.knowledgeStats === 'object' ? value.knowledgeStats : {}
    }
  } catch {
    return { attempts: [], wrongIds: [], masteredIds: [], testedKnowledgeIds: [], knowledgeStats: {} }
  }
}

function saveProgress(progress) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(progress)) } catch {}
}

function loadResearch() {
  let raw = ''
  try {
    raw = localStorage.getItem(RESEARCH_KEY) || ''
    return { data: normalizeResearchData(JSON.parse(raw || '{}')), canPersist: true, notice: '' }
  } catch {
    const backupKey = `${RESEARCH_KEY}.corrupt.${Date.now()}`
    try { if (raw) localStorage.setItem(backupKey, raw) } catch {}
    return { data: normalizeResearchData({}), canPersist: false, notice: raw ? `检测到损坏的本地数据，原文已备份到 ${backupKey}` : '本地存储暂时不可用，本次更改可能无法保存' }
  }
}

function sameAnswer(left = [], right = []) {
  const a = [...left].sort((x, y) => x - y)
  const b = [...right].sort((x, y) => x - y)
  return a.length === b.length && a.every((value, index) => value === b[index])
}

function makePaper(mode, count, progress) {
  let candidates = QUESTION_BANK
  if (mode === 'wrong') {
    const wrong = new Set(progress.wrongIds)
    candidates = QUESTION_BANK.filter((question) => wrong.has(question.id))
  } else if (mode === 'cycle') {
    candidates = QUESTION_BANK.filter((question) => question.source.includes('周期论'))
  } else if (mode === 'practice') {
    candidates = QUESTION_BANK.filter((question) => question.source.includes('野人哥'))
  } else if (mode.startsWith('chapter:')) {
    const key = mode.slice(8)
    candidates = QUESTION_BANK.filter((question) => `${question.source}::${question.chapter}` === key)
  }
  if (!candidates.length) candidates = QUESTION_BANK
  const tested = new Set(progress.testedKnowledgeIds || [])
  const stats = progress.knowledgeStats || {}
  const scored = candidates.map((question) => {
    const ids = question.knowledgeIds || []
    const untested = ids.filter((id) => !tested.has(id)).length
    const weak = ids.reduce((sum, id) => sum + ((stats[id]?.wrong || 0) > (stats[id]?.correct || 0) ? 1 : 0), 0)
    const attempts = ids.reduce((sum, id) => sum + (stats[id]?.correct || 0) + (stats[id]?.wrong || 0), 0)
    return { question, priority: untested * 100 + weak * 30 - attempts + Math.random() }
  }).sort((a, b) => b.priority - a.priority)
  return scored.slice(0, Math.min(count, scored.length)).map((item) => item.question)
}

function coverageOf(progress) {
  const tested = new Set(progress.testedKnowledgeIds || [])
  const mastered = new Set(progress.masteredIds || [])
  return {
    tested: KNOWLEDGE_CATALOG.filter((item) => tested.has(item.id)).length,
    mastered: KNOWLEDGE_CATALOG.filter((item) => mastered.has(item.id)).length,
    total: KNOWLEDGE_CATALOG.length,
    percent: KNOWLEDGE_CATALOG.length ? Math.round((tested.size / KNOWLEDGE_CATALOG.length) * 100) : 0
  }
}

function selectedLabel(question, answer) {
  if (!answer?.length) return '未作答'
  return answer.map((index) => `${String.fromCharCode(65 + index)}. ${question.options[index]}`).join('；')
}

